const constant = require('../lib/constant');
const _ = require('lodash');

/**
 * hash.js:
 * hdel key field [field ...]
 * hexists key field
 * hget key field
 * hgetall key
 * hincrby key field increment
 * hkeys key
 * hlen key
 * hmget key field [field ...]
 * hmset key field value
 * hset key field value
 * hsetnx key field value
 */
module.exports = (common) => {
  const operations = {
    * hdel(key, ...fields) {
      fields = common.getFieldToArray(fields, true);
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || fields === null) {
        return 0;
      }
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.HASH, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        if (objVer === null || objVer.value === null) {
          return 0;
        }
        const obj = objVer.value;
        let count = 0;
        fields.forEach(field => {
          if (obj[field]) {
            delete obj[field];
            count++;
          }
        });
        if (count) {
          const ret = yield common.setStringEx(key, common.toStringWithType(obj, constant.TYPE.HASH), objVer.ver);
          if (ret === undefined) {
            return undefined;
          } else if (ret) {
            return count;
          }
        }
      }
      return 0;
    },

    * hexists(key, ...fields) {
      // forceMaster
      let forceMaster;
      if (fields.length > 1 && fields[fields.length - 1] === constant.CONSTANT.FORCEMASTER) {
        forceMaster = constant.CONSTANT.FORCEMASTER;
        fields = fields.slice(0, fields.length - 1);
      }
      fields = common.getFieldToArray(fields, true);
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || fields === null) {
        return 0;
      }
      const obj = yield operations.hgetall(key, forceMaster);
      if (obj === undefined) {
        return undefined;
      } else if (obj === null) {
        return 0;
      }
      let count = 0;
      fields.forEach(field => {
        if (obj[field]) {
          count++;
        }
      });
      return count;
    },

    * hget(key, field, forceMaster) {
      /* istanbul ignore if */
      if (_.isNumber(field)) {
        field = field.toString();
      }
      if (common.isNotStrOrEmpty(key) || common.isNotStrOrEmpty(field)) {
        return null;
      }
      const obj = yield operations.hgetall(key, forceMaster);
      if (obj === undefined) {
        return undefined;
      }
      if (obj === null) {
        return null;
      }
      return obj[field] || null;
    },

    * hgetall(key, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return null;
      }
      return yield common.getValue(key, constant.TYPE.HASH, forceMaster);
    },

    * hincrby(key, field, increment) {
      /* istanbul ignore if */
      if (_.isNumber(field)) {
        field = field.toString();
      }
      if (common.isNotStrOrEmpty(key) || common.isNotStrOrEmpty(field)) {
        return false;
      }
      increment = common.convertToInt(increment);
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.HASH, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        let obj;
        if (objVer === null || objVer.value === null) {
          obj = {};
        } else {
          obj = objVer.value;
        }
        obj[field] = (obj[field] ? common.convertToInt(obj[field]) + increment : increment).toString();
        const ret = yield common.setStringEx(key, common.toStringWithType(obj, constant.TYPE.HASH), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return obj[field] || null;
        }
      }
      /* istanbul ignore next */
      return false;
    },

    * hkeys(key, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return null;
      }
      const value = yield operations.hgetall(key, forceMaster);
      if (value === undefined) {
        return undefined;
      }
      if (value === null) {
        return null;
      }
      return Object.keys(value);
    },

    * hlen(key, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return 0;
      }
      const keys = yield operations.hkeys(key, forceMaster);
      if (keys === undefined) {
        return undefined;
      }
      return keys === null ? 0 : keys.length;
    },

    * hmget(key, ...fields) {
      // forceMaster
      let forceMaster;
      if (fields.length > 1 && fields[fields.length - 1] === constant.CONSTANT.FORCEMASTER) {
        forceMaster = constant.CONSTANT.FORCEMASTER;
        fields = fields.slice(0, fields.length - 1);
      }
      fields = common.getFieldToArray(fields, true);
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || fields === null) {
        return null;
      }
      const obj = yield operations.hgetall(key, forceMaster);
      if (obj === undefined) {
        return undefined;
      }
      if (obj === null) {
        return null;
      }
      const result = {};
      fields.forEach(field => {
        if (obj[field]) {
          result[field] = obj[field];
        }
      });
      return result;
    },

    * hmset(key, ...kvs) {
      const newObj = common.getFieldToObj(kvs);
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || kvs === null || newObj === null) {
        return false;
      }
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.HASH, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        let origObj;
        if (objVer === null || objVer.value === null) {
          origObj = {};
        } else {
          origObj = objVer.value;
        }
        for (const field in newObj) {
          origObj[field] = newObj[field];
        }
        const ret = yield common.setStringEx(key, common.toStringWithType(origObj, constant.TYPE.HASH), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return true;
        }
      }
      /* istanbul ignore next */
      return false;
    },

    * hset(key, field, value) {
      /* istanbul ignore if */
      if (_.isNumber(field)) {
        field = field.toString();
      }
      if (common.isNotStrOrEmpty(key) || common.isNotStrOrEmpty(field) || value === null || value === undefined) {
        return false;
      }
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.HASH, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        let obj;
        if (objVer === null || objVer.value === null) {
          obj = {};
        } else {
          obj = objVer.value;
        }
        obj[field] = value;
        const ret = yield common.setStringEx(key, common.toStringWithType(obj, constant.TYPE.HASH), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return true;
        }
      }
      /* istanbul ignore next */
      return false;
    },

    * hsetnx(key, field, value) {
      /* istanbul ignore if */
      if (_.isNumber(field)) {
        field = field.toString();
      }
      if (common.isNotStrOrEmpty(key) || common.isNotStrOrEmpty(field) || value === null || value === undefined) {
        return false;
      }
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.HASH, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        let obj;
        if (objVer === null || objVer.value === null) {
          obj = {};
        } else {
          obj = objVer.value;
        }
        if (obj[field] === null || obj[field] === undefined) {
          obj[field] = value;
        } else {
          return false;
        }
        const ret = yield common.setStringEx(key, common.toStringWithType(obj, constant.TYPE.HASH), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return true;
        }
      }
      /* istanbul ignore next */
      return false;
    },
  };
  return operations;
};
